import{f as a,o,c as t,a2 as d}from"./chunks/framework.Cd9rfTEn.js";const g=JSON.parse('{"title":"Reglas de negocio de Procoop extraídas del código","description":"","frontmatter":{},"headers":[],"relativePath":"relevamiento/reglas-negocio/00-indice.md","filePath":"relevamiento/reglas-negocio/00-indice.md","lastUpdated":null}'),r={name:"relevamiento/reglas-negocio/00-indice.md"};function s(n,e,i,c,l,u){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="reglas-de-negocio-de-procoop-extraidas-del-codigo" tabindex="-1">Reglas de negocio de Procoop extraídas del código <a class="header-anchor" href="#reglas-de-negocio-de-procoop-extraidas-del-codigo" aria-label="Permalink to &quot;Reglas de negocio de Procoop extraídas del código&quot;">​</a></h1><p>Documentos generados a partir del código C# descompilado de Procoop 10.4.6.722 (<code>binarios/decompilado/</code>). Cada documento describe las reglas en prosa y cita la clase, el método y el archivo:línea de donde salen, para poder verificarlas.</p><p>Complementan al relevamiento funcional por pantallas (<a href="./../README"><code>../README.md</code></a>) y a la <a href="./../definicion-funcional-alcance">definición funcional del alcance</a>.</p><p><strong>[VERIFICAR]</strong> marca las reglas cuyo comportamiento depende de datos o parámetros que solo se confirman en la base de la cooperativa.</p><h2 id="documentos" tabindex="-1">Documentos <a class="header-anchor" href="#documentos" aria-label="Permalink to &quot;Documentos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Documento</th><th>Tema</th></tr></thead><tbody><tr><td>01</td><td><a href="./01-calculo-factura-servicios">Cálculo de la factura de servicios</a></td><td>Cargo fijo, tramos, prorrateo, demanda, factor de potencia, lenguaje de fórmulas de cargos adicionales, cuadros tarifarios, impuestos, redondeo</td></tr><tr><td>02</td><td><a href="./02-facturacion-masiva-y-comprobantes">Facturación masiva y comprobantes</a></td><td>Proceso mensual, numeración, vencimientos, anulación, recategorización, retroactivos, impresión y código de barras</td></tr><tr><td>03</td><td><a href="./03-afip-facturacion-electronica-e-iva">ARCA, facturación electrónica e IVA</a></td><td>WSAA, CAE/CAEA, mapeo a códigos ARCA, padrón, libro IVA</td></tr><tr><td>04</td><td><a href="./04-mora-intereses-y-corte">Mora, intereses y corte</a></td><td>Intereses, instancias de mora, corte y reconexión, planes de pago</td></tr><tr><td>05</td><td><a href="./05-cobranzas-cajas-y-entes-recaudadores">Cobranzas, cajas y entes recaudadores</a></td><td>Caja, anulaciones, imputación, Red Link, SIRO, débitos, prepaga</td></tr><tr><td>06</td><td><a href="./06-titulares-servicios-medidores-y-consumos">Titulares, servicios, medidores y consumos</a></td><td>Altas y bajas, medidores, lecturas, validación de consumos, telemedición</td></tr><tr><td>07</td><td><a href="./07-tecnica-reclamos-gis-y-telefonia">Técnica, reclamos, GIS y telefonía</a></td><td>Órdenes de trabajo, reclamos, red, tickets, tarificación telefónica</td></tr><tr><td>08</td><td><a href="./08-tesoreria-contabilidad-compras-stock-sueldos">Tesorería, contabilidad, compras, stock y sueldos</a></td><td>Back-office administrativo</td></tr><tr><td>09</td><td><a href="./09-parametros-y-configuracion">Parámetros y configuración</a></td><td>Catálogo de 1.536 parámetros <code>Busca_V2_*</code>, seguridad, arquitectura</td></tr><tr><td>10</td><td><a href="./10-integraciones-externas">Integraciones externas</a></td><td>Portal CoopOnline, agente, mail, SMS, app, entes reguladores</td></tr><tr><td>11</td><td><a href="./11-especificas-laguna-larga">Específicas de Laguna Larga</a></td><td>Importador Red Link propio, código de barras SIRO, ramas de código para LAG, consultas para confirmar en la base</td></tr><tr><td>12</td><td><a href="./12-configuracion-real-laguna-larga">Configuración real de Laguna Larga</a></td><td>Sigla, entes recaudadores, pasarelas y parámetros leídos de la base demo</td></tr><tr><td>13</td><td><a href="./13-pasarelas-de-pago-e-interbanking">Pasarelas de pago e Interbanking</a></td><td>Pagos360, SIRO, MercadoPago, Macro y otras; webhooks, conciliación, Interbanking</td></tr></tbody></table><h2 id="cobertura-del-codigo" tabindex="-1">Cobertura del código <a class="header-anchor" href="#cobertura-del-codigo" aria-label="Permalink to &quot;Cobertura del código&quot;">​</a></h2><p>Medida al 4/11/2026, después de la segunda pasada. Un método cuenta como documentado si su nombre aparece en algún documento, ya sea con su regla o en una línea &quot;Métodos sin regla de negocio&quot; (revisado, sin lógica). Es una medida aproximada: un nombre común puede coincidir por casualidad, y un método descrito con otras palabras no se cuenta. Antes de la segunda pasada, Facturación estaba en 40 %, Cobranzas en 48 %, Titulares/Servicios/Consumos en 22 %, Tesorería y Contabilidad en 35 % y el portal en 19 % de métodos.</p><table tabindex="0"><thead><tr><th>Área</th><th>Archivos citados</th><th>Métodos documentados</th></tr></thead><tbody><tr><td>Facturación (cálculo, masiva, archivos, códigos de barra genéricos)</td><td>80/102 (78 %)</td><td>796/1007 (79 %)</td></tr><tr><td>ARCA (WSAA, WSFEv1, padrones)</td><td>22/128 (17 %)</td><td>44/88 (50 %)</td></tr><tr><td>Cobranzas, mora y financiación</td><td>39/42 (92 %)</td><td>509/521 (97 %)</td></tr><tr><td>Titulares, servicios y consumos</td><td>39/74 (52 %)</td><td>464/728 (63 %)</td></tr><tr><td>Telemedición y app móvil</td><td>39/49 (79 %)</td><td>304/505 (60 %)</td></tr><tr><td>Técnica, GIS, tickets y actividades</td><td>51/61 (83 %)</td><td>300/358 (83 %)</td></tr><tr><td>Telefonía</td><td>13/33 (39 %)</td><td>72/238 (30 %)</td></tr><tr><td>Tesorería y contabilidad</td><td>18/23 (78 %)</td><td>269/289 (93 %)</td></tr><tr><td>Compras, stock, fabricación y sueldos</td><td>30/31 (96 %)</td><td>339/616 (55 %)</td></tr><tr><td>Núcleo, configuración, plantillas y tablero</td><td>62/136 (45 %)</td><td>250/980 (25 %)</td></tr><tr><td>Portal CoopOnline, mails, agente y varios</td><td>25/41 (60 %)</td><td>203/207 (98 %)</td></tr><tr><td>Formularios de <code>Configuracion</code></td><td>67/311 (21 %)</td><td>56/328 (17 %)</td></tr><tr><td><code>ProcoopNet</code> (ejecutable)</td><td>9/16 (56 %)</td><td>11/37 (29 %)</td></tr><tr><td><code>ProMod_WebService</code> (solo clases de servicio)</td><td>26/26 (100 %)</td><td>50/61 (81 %)</td></tr><tr><td>Entes por cooperativa (<code>Cobranzas.Entidades.*</code>)</td><td>375/431 (87 %)</td><td>895/909 (98 %)</td></tr><tr><td>Códigos de barra por cooperativa</td><td>9/91 (9 %)</td><td>464/464 (100 %)</td></tr></tbody></table><h2 id="que-quedo-afuera-y-por-que" tabindex="-1">Qué quedó afuera y por qué <a class="header-anchor" href="#que-quedo-afuera-y-por-que" aria-label="Permalink to &quot;Qué quedó afuera y por qué&quot;">​</a></h2><p><strong>Excluido a propósito:</strong></p><ul><li><strong>Interfaces de cobranza y códigos de barras de otras cooperativas.</strong> Solo se describe el patrón común; lo de Laguna Larga está en el documento 11. Su cobertura alta de métodos es engañosa: los nombres coinciden con los del patrón genérico.</li><li><strong>Clases proxy del WSDL de ARCA</strong> (<code>WSFEV1</code>, 107 archivos). Solo se documentan las operaciones y campos que Procoop usa realmente; por eso los archivos citados son 17 %.</li><li><strong>SDK de MercadoPago, Request/Response de <code>ProMod_WebService</code>, Interop de Office, PortableDevice y GoogleEarth.</strong> Son contratos de API o librerías, no reglas.</li><li><strong>Telefonía fuera de tasación y facturación:</strong> red física, IVR, SMS/WhatsApp, guía e informes de llamadas.</li></ul><p><strong>Pendiente: la segunda pasada se cortó</strong> el 4/11/2026 porque la cuenta de Cursor tiene una factura impaga. Lo que los agentes alcanzaron a escribir quedó guardado. Falta:</p><ul><li><strong>09 — reglas en formularios de <code>Configuracion</code> y <code>ProcoopNet</code>, plantillas y tablero</strong> (prioridad B). No llegó a editar el documento. Por eso esas áreas siguen bajas: formularios en 17 %, núcleo en 25 %.</li><li><strong>02 — facturación masiva:</strong> avanzó de 768 a 926 líneas sin terminar la lista de métodos.</li><li><strong>04 — validaciones de las pantallas de mora, tasas y planes</strong> en <code>ProMod_GestionMora</code> y <code>ProMod_Cobranzas</code>. Ya están descompiladas, pero no se revisaron.</li><li><strong>06 — telemedición y app móvil</strong> método por método. Quedan las reglas por familia de proveedor de la primera pasada.</li><li><strong>08 y 10:</strong> avanzaron (08 de 639 a 1.074 líneas, 10 de 208 a 493) sin el resumen final de cada agente.</li><li><strong>Titulares:</strong> informes y exportaciones revisados solo por muestreo (<code>clsViviendas</code>, <code>clsWEB</code>, <code>clsCirculares</code>, <code>clsEvolucionDeuda</code>, <code>clsPadronTitular</code>).</li></ul><p><strong>Fuera del código:</strong> las funciones <code>FORMULA_CARGO*</code> y otros procedimientos almacenados viven en la base de cada cooperativa. Para Laguna Larga hay que leerlos en <code>PR_LAG_DEMO</code>.</p><p>El código de Procoop es de terceros: estos documentos solo describen reglas y no deben incluir copias del código fuente. No se suben a ningún repositorio.</p>',16)])])}const m=a(r,[["render",s]]);export{g as __pageData,m as default};
